contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: supply seedDrugs and ensure caller has balance 0 change needed
    function run(uint256 seedDrugs) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        // ensure we can call seedMarket (market must be zero initially) and that getFreeKilo precondition holds
        // seedMarket is payable but does not require msg.value; we don't send ETH here
        // call seedMarket to initialize the contract
        c.seedMarket{value: 0}(seedDrugs); if (__ESBMC_reverted()) return;

        // require that before calling getFreeKilo the caller indeed has zero kilos
        require(c.getMyKilo() == 0);

        // attempt getFreeKilo and capture revert status
        bool reverted;
        c.getFreeKilo(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After a successful seedMarket, getFreeKilo should not revert when caller has zero kilos,
        // and should set getMyKilo() equal to STARTING_KILOS. We observe STARTING_KILOS via its public getter.
        assert(!reverted && c.getMyKilo() == c.STARTING_KILOS());
    }

    receive() external payable {}
}

