// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedDrugs) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        try c.seedMarket{value: 0}(seedDrugs) {} catch { return; }
        vm.assume(c.getMyKilo() == 0);
        bool reverted;
        try c.getFreeKilo() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && c.getMyKilo() == c.STARTING_KILOS());
    }

    function testFuzz_run(uint256 seedDrugs) public {
        _run(seedDrugs);
    }

    receive() external payable {}
}
